@import "tailwindcss";

:root {
  --background: #ffffff;
  --foreground: #171717;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #0a0a0a;
    --foreground: #ededed;
  }
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: Arial, Helvetica, sans-serif;
}

tool_input.content:
@import "tailwindcss";

@theme inline {
  --color-bg: #000000;
  --color-bg-card: #0a0a0a;
  --color-bg-card-hover: #111111;
  --color-border: #1a1a1a;
  --color-text: #ffffff;
  --color-text-muted: #888888;
  --color-accent: #a855f7;
  --color-accent-2: #ec4899;
  --color-safe: #22c55e;
  --color-owl: #6366f1;
  --color-warn: #f59e0b;
  --color-danger: #ef4444;
  --font-sans: 'Inter', -apple-system, sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; }

body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Safe area for mobile notch */
body { padding-top: env(safe-area-inset-top); }

/* Gradient utilities */
.gradient-bg { background: linear-gradient(135deg, #a855f7, #ec4899); }
.gradient-bg-subtle { background: linear-gradient(135deg, rgba(168,85,247,0.15), rgba(236,72,153,0.15)); }
.gradient-text {
  background: linear-gradient(135deg, #a855f7, #ec4899);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.shadow-glow { box-shadow: 0 0 40px rgba(168,85,247,0.3); }
.shadow-glow-sm { box-shadow: 0 0 20px rgba(168,85,247,0.2); }

/* Animations */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes float {
  0%, 100% { transform: translate(0,0); }
  33% { transform: translate(30px,-30px); }
  66% { transform: translate(-20px,20px); }
}
@keyframes pulse-dot {
  0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(129,140,248,0.4); }
  50% { opacity: 0.6; box-shadow: 0 0 0 8px rgba(129,140,248,0); }
}
@keyframes phoneFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-15px); }
}

.animate-fade-up { animation: fadeUp 0.4s ease both; }
.animate-float { animation: float 8s ease-in-out infinite; }
.animate-pulse-dot { animation: pulse-dot 2s ease-in-out infinite; }
.animate-phone-float { animation: phoneFloat 6s ease-in-out infinite; }

/* Hide scrollbar but keep scroll */
.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

/* Mobile bottom nav safe area */
.pb-safe { padding-bottom: calc(72px + env(safe-area-inset-bottom)); }

/* Touch-friendly tap targets */
.tap-target { min-height: 44px; min-width: 44px; }

